-- Bank Spesialis (docs/poa-bank-spesialis/): pasangan spesialis dokter -> produk. Produk di tabel ini = Produk Kontes.
-- Dikelola ADMIN dari halaman Admin; seed awal dari sheet "Bank Spesialis" (677 pasangan).
CREATE TABLE "BankSpesialis" (
    "id" TEXT NOT NULL,
    "spesialis" TEXT NOT NULL,
    "kodeProduk" TEXT NOT NULL,
    "namaProduk" TEXT NOT NULL,
    "keterangan" TEXT,
    "updatedByNip" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "BankSpesialis_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "BankSpesialis_spesialis_kodeProduk_key" ON "BankSpesialis"("spesialis", "kodeProduk");
CREATE INDEX "BankSpesialis_kodeProduk_idx" ON "BankSpesialis"("kodeProduk");

